CREATE TYPE public.workspace_tier AS ENUM ('Free','Pro_Founder','Enterprise_VC');
CREATE TYPE public.workspace_role AS ENUM ('owner','admin','member','recruiter','founder');
CREATE TYPE public.bounty_status AS ENUM ('open','assigned','submitted','paid');
CREATE TYPE public.bounty_payout AS ENUM ('Milestone','Completion','RevShare');
CREATE TYPE public.credential_claim AS ENUM ('Top_1_Percent_Committer','Successful_Exit','AI_Ship_Streak');
CREATE TABLE public.workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(name) BETWEEN 2 AND 100),slug text NOT NULL UNIQUE CHECK(slug ~ '^[a-z0-9][a-z0-9-]{1,59}$'),domain text,logo_url text,owner_id uuid REFERENCES public.profiles(id),tier public.workspace_tier NOT NULL DEFAULT 'Free',is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.workspaces TO anon,authenticated; GRANT ALL ON public.workspaces TO service_role;
ALTER TABLE public.workspaces ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.workspace_members(workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,role public.workspace_role NOT NULL DEFAULT 'member',PRIMARY KEY(workspace_id,user_id));
GRANT SELECT ON public.workspace_members TO authenticated; GRANT ALL ON public.workspace_members TO service_role;
ALTER TABLE public.workspace_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.workspace_access(_workspace uuid,_manage boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=_workspace AND user_id=auth.uid() AND (NOT _manage OR role IN('owner','admin'))) $$;
REVOKE ALL ON FUNCTION public.workspace_access(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.workspace_access(uuid,boolean) TO authenticated;
CREATE POLICY workspace_read ON public.workspaces FOR SELECT TO anon,authenticated USING(is_demo OR owner_id=auth.uid() OR EXISTS(SELECT 1 FROM public.workspace_members m WHERE m.workspace_id=id AND m.user_id=auth.uid()));
CREATE POLICY membership_read ON public.workspace_members FOR SELECT TO authenticated USING(public.workspace_access(workspace_id));
CREATE TABLE public.workspace_projects(workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,PRIMARY KEY(workspace_id,project_id),UNIQUE(project_id));
GRANT SELECT ON public.workspace_projects TO anon,authenticated; GRANT ALL ON public.workspace_projects TO service_role;
ALTER TABLE public.workspace_projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY portfolio_read ON public.workspace_projects FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.workspaces w WHERE w.id=workspace_id));
CREATE TABLE public.workspace_candidate_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,request_id uuid NOT NULL REFERENCES public.connect_requests(id) ON DELETE CASCADE,author_id uuid NOT NULL REFERENCES public.profiles(id),note text NOT NULL CHECK(length(note) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.workspace_candidate_notes TO authenticated; GRANT ALL ON public.workspace_candidate_notes TO service_role;
ALTER TABLE public.workspace_candidate_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY notes_read ON public.workspace_candidate_notes FOR SELECT TO authenticated USING(public.workspace_access(workspace_id));
CREATE TABLE public.workspace_candidates(workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,builder_id uuid NOT NULL REFERENCES public.profiles(id),stage text NOT NULL DEFAULT 'saved' CHECK(stage IN('saved','reviewing','shortlisted','archived')),added_by uuid NOT NULL REFERENCES public.profiles(id),PRIMARY KEY(workspace_id,builder_id));
GRANT SELECT ON public.workspace_candidates TO authenticated; GRANT ALL ON public.workspace_candidates TO service_role;
ALTER TABLE public.workspace_candidates ENABLE ROW LEVEL SECURITY;
CREATE POLICY pool_read ON public.workspace_candidates FOR SELECT TO authenticated USING(public.workspace_access(workspace_id));
CREATE FUNCTION public.create_workspace(_name text,_slug text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE wid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required' USING ERRCODE='42501'; END IF; INSERT INTO workspaces(name,slug,owner_id) VALUES(btrim(_name),lower(btrim(_slug)),auth.uid()) RETURNING id INTO wid; INSERT INTO workspace_members VALUES(wid,auth.uid(),'owner'); RETURN wid; END $$;
REVOKE ALL ON FUNCTION public.create_workspace(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_workspace(text,text) TO authenticated;
CREATE FUNCTION public.manage_workspace_member(_workspace uuid,_user uuid,_role public.workspace_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.workspace_access(_workspace,true) OR EXISTS(SELECT 1 FROM workspaces WHERE id=_workspace AND is_demo) THEN RAISE EXCEPTION 'Workspace administrator required' USING ERRCODE='42501'; END IF; IF _role='owner' OR EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=_workspace AND user_id=_user AND role='owner') THEN RAISE EXCEPTION 'Ownership cannot be reassigned here' USING ERRCODE='42501'; END IF; INSERT INTO workspace_members VALUES(_workspace,_user,_role) ON CONFLICT(workspace_id,user_id) DO UPDATE SET role=excluded.role; END $$;
REVOKE ALL ON FUNCTION public.manage_workspace_member(uuid,uuid,public.workspace_role) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.manage_workspace_member(uuid,uuid,public.workspace_role) TO authenticated;
CREATE FUNCTION public.attach_workspace_project(_workspace uuid,_project uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.workspace_access(_workspace,true) OR NOT EXISTS(SELECT 1 FROM projects WHERE id=_project AND user_id=auth.uid() AND NOT is_demo) OR EXISTS(SELECT 1 FROM workspaces WHERE id=_workspace AND is_demo) THEN RAISE EXCEPTION 'Own a real project and administer its workspace' USING ERRCODE='42501'; END IF; INSERT INTO workspace_projects VALUES(_workspace,_project) ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.attach_workspace_project(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.attach_workspace_project(uuid,uuid) TO authenticated;
CREATE FUNCTION public.portfolio_pipeline(_workspace uuid) RETURNS TABLE(request_id uuid,project_id uuid,project_title text,builder_id uuid,builder_name text,pitch_sentence text,status text,created_at timestamptz,response_hours double precision) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.workspace_access(_workspace) THEN RAISE EXCEPTION 'Workspace membership required' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT r.id,p.id,p.title,r.applicant_id,b.full_name,r.pitch_sentence,r.status::text,r.created_at,CASE WHEN r.status<>'pending' THEN extract(epoch FROM(r.updated_at-r.created_at))::double precision/3600 END FROM workspace_projects wp JOIN projects p ON p.id=wp.project_id JOIN connect_requests r ON r.project_id=p.id JOIN profiles b ON b.id=r.applicant_id WHERE wp.workspace_id=_workspace AND NOT r.flagged; END $$;
REVOKE ALL ON FUNCTION public.portfolio_pipeline(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.portfolio_pipeline(uuid) TO authenticated;
CREATE FUNCTION public.save_candidate_note(_workspace uuid,_request uuid,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.workspace_access(_workspace) OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=_workspace AND user_id=auth.uid() AND role IN('owner','admin','recruiter','founder')) OR NOT EXISTS(SELECT 1 FROM workspace_projects wp JOIN connect_requests r ON r.project_id=wp.project_id WHERE wp.workspace_id=_workspace AND r.id=_request) THEN RAISE EXCEPTION 'Recruiting access required' USING ERRCODE='42501'; END IF; INSERT INTO workspace_candidate_notes(workspace_id,request_id,author_id,note) VALUES(_workspace,_request,auth.uid(),btrim(_note)); END $$;
REVOKE ALL ON FUNCTION public.save_candidate_note(uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_candidate_note(uuid,uuid,text) TO authenticated;
CREATE FUNCTION public.save_workspace_candidate(_workspace uuid,_builder uuid,_stage text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.workspace_access(_workspace) OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=_workspace AND user_id=auth.uid() AND role IN('owner','admin','recruiter','founder')) OR EXISTS(SELECT 1 FROM profiles WHERE id=_builder AND is_demo) THEN RAISE EXCEPTION 'Recruiting access and real builder required' USING ERRCODE='42501'; END IF; INSERT INTO workspace_candidates VALUES(_workspace,_builder,_stage,auth.uid()) ON CONFLICT(workspace_id,builder_id) DO UPDATE SET stage=excluded.stage; END $$;
REVOKE ALL ON FUNCTION public.save_workspace_candidate(uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_workspace_candidate(uuid,uuid,text) TO authenticated;
CREATE TABLE public.project_bounties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,title text NOT NULL CHECK(length(title) BETWEEN 4 AND 160),description text NOT NULL DEFAULT '',reward_amount numeric NOT NULL CHECK(reward_amount>0),currency text NOT NULL DEFAULT 'USD' CHECK(currency IN('USD','USDC','EUR')),status public.bounty_status NOT NULL DEFAULT 'open',payout_type public.bounty_payout NOT NULL DEFAULT 'Milestone',tech_stack text[] NOT NULL DEFAULT '{}',duration text NOT NULL DEFAULT '1-2 weeks' CHECK(duration IN('<5 hrs','1-2 days','1-2 weeks')),assignee_id uuid REFERENCES public.profiles(id),delivery_url text,owner_signed_at timestamptz,builder_signed_at timestamptz,funding_status text NOT NULL DEFAULT 'unfunded' CHECK(funding_status IN('unfunded','funded','released')),is_demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.project_bounties TO anon,authenticated; GRANT ALL ON public.project_bounties TO service_role;
ALTER TABLE public.project_bounties ENABLE ROW LEVEL SECURITY;
CREATE POLICY bounty_public ON public.project_bounties FOR SELECT TO anon,authenticated USING(true);
CREATE FUNCTION public.create_bounty(_project uuid,_title text,_description text,_amount numeric,_currency text,_duration text,_payout public.bounty_payout) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; BEGIN IF NOT EXISTS(SELECT 1 FROM projects WHERE id=_project AND user_id=auth.uid() AND NOT is_demo) THEN RAISE EXCEPTION 'Real project owner required' USING ERRCODE='42501'; END IF; INSERT INTO project_bounties(project_id,title,description,reward_amount,currency,duration,payout_type,tech_stack) SELECT id,_title,_description,_amount,_currency,_duration,_payout,tech_stack FROM projects WHERE id=_project RETURNING id INTO bid; RETURN bid; END $$;
REVOKE ALL ON FUNCTION public.create_bounty(uuid,text,text,numeric,text,text,public.bounty_payout) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_bounty(uuid,text,text,numeric,text,text,public.bounty_payout) TO authenticated;
CREATE FUNCTION public.bounty_action(_bounty uuid,_action text,_delivery text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b project_bounties; owner uuid; BEGIN SELECT * INTO b FROM project_bounties WHERE id=_bounty FOR UPDATE; SELECT user_id INTO owner FROM projects WHERE id=b.project_id; IF b.id IS NULL OR b.is_demo OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Real bounty and sign in required' USING ERRCODE='42501'; END IF; IF _action='claim' AND b.status='open' AND owner<>auth.uid() THEN UPDATE project_bounties SET assignee_id=auth.uid(),status='assigned' WHERE id=b.id; ELSIF _action='submit' AND b.status='assigned' AND b.assignee_id=auth.uid() AND _delivery ~ '^https://github.com/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+/(pull/[0-9]+|commit/[a-f0-9]+)$' THEN UPDATE project_bounties SET status='submitted',delivery_url=_delivery WHERE id=b.id; ELSIF _action='sign' AND b.status='submitted' AND auth.uid() IN(owner,b.assignee_id) THEN UPDATE project_bounties SET owner_signed_at=CASE WHEN auth.uid()=owner THEN now() ELSE owner_signed_at END,builder_signed_at=CASE WHEN auth.uid()=b.assignee_id THEN now() ELSE builder_signed_at END WHERE id=b.id; ELSE RAISE EXCEPTION 'Invalid bounty transition or participant' USING ERRCODE='42501'; END IF; END $$;
REVOKE ALL ON FUNCTION public.bounty_action(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.bounty_action(uuid,text,text) TO authenticated;
CREATE TABLE public.builder_verifiable_credentials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,issuer text NOT NULL DEFAULT 'Slyk_Proof_Engine',claim_type public.credential_claim NOT NULL,proof_hash text NOT NULL CHECK(proof_hash ~ '^[a-f0-9]{64}$'),verified_at timestamptz NOT NULL DEFAULT now(),source text NOT NULL CHECK(source IN('github','stripe')),event_id text NOT NULL,UNIQUE(source,event_id,claim_type));
GRANT SELECT ON public.builder_verifiable_credentials TO anon,authenticated; GRANT ALL ON public.builder_verifiable_credentials TO service_role;
ALTER TABLE public.builder_verifiable_credentials ENABLE ROW LEVEL SECURITY;
CREATE POLICY credentials_public ON public.builder_verifiable_credentials FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.credential_verified_events(source text NOT NULL,event_id text NOT NULL,user_id uuid NOT NULL REFERENCES public.profiles(id),payload jsonb NOT NULL,verified_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(source,event_id));
GRANT ALL ON public.credential_verified_events TO service_role;
ALTER TABLE public.credential_verified_events ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.immutable_credential() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Verified evidence is immutable'; END $$;
CREATE TRIGGER credential_immutable BEFORE UPDATE OR DELETE ON public.builder_verifiable_credentials FOR EACH ROW EXECUTE FUNCTION public.immutable_credential();
CREATE TRIGGER event_immutable BEFORE UPDATE OR DELETE ON public.credential_verified_events FOR EACH ROW EXECUTE FUNCTION public.immutable_credential();
CREATE FUNCTION public.issue_verified_credential(_source text,_event text,_claim public.credential_claim) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE e credential_verified_events; cid uuid; BEGIN SELECT * INTO e FROM credential_verified_events WHERE source=_source AND event_id=_event; IF e.user_id IS NULL OR EXISTS(SELECT 1 FROM profiles WHERE id=e.user_id AND is_demo) THEN RAISE EXCEPTION 'Verified real event required'; END IF; IF _claim='Successful_Exit' THEN RAISE EXCEPTION 'Payment alone does not verify an exit'; END IF; IF _claim='Top_1_Percent_Committer' THEN RAISE EXCEPTION 'Population percentile verification is required'; END IF; IF _source<>'github' OR _claim<>'AI_Ship_Streak' OR (e.payload->>'verified_ai_release_days')::int<7 THEN RAISE EXCEPTION 'Verified seven-day AI release streak required'; END IF; INSERT INTO builder_verifiable_credentials(user_id,claim_type,proof_hash,source,event_id) VALUES(e.user_id,_claim,encode(digest(jsonb_build_object('source',e.source,'event_id',e.event_id,'subject',e.user_id,'claim',_claim,'payload',e.payload)::text,'sha256'),'hex'),_source,_event) ON CONFLICT DO NOTHING RETURNING id INTO cid; RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.issue_verified_credential(text,text,public.credential_claim) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.issue_verified_credential(text,text,public.credential_claim) TO service_role;
CREATE TABLE public.builder_passports(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,username text NOT NULL UNIQUE CHECK(username ~ '^[a-z0-9][a-z0-9-]{1,59}$'),headline text NOT NULL DEFAULT '',is_demo boolean NOT NULL DEFAULT false,contribution_graph jsonb NOT NULL DEFAULT '{}');
GRANT SELECT ON public.builder_passports TO anon,authenticated; GRANT ALL ON public.builder_passports TO service_role;
ALTER TABLE public.builder_passports ENABLE ROW LEVEL SECURITY;
CREATE POLICY passport_public ON public.builder_passports FOR SELECT TO anon,authenticated USING(true);
CREATE FUNCTION public.save_builder_passport(_username text,_headline text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR length(_headline)>200 OR EXISTS(SELECT 1 FROM profiles WHERE id=auth.uid() AND is_demo) THEN RAISE EXCEPTION 'Real builder required' USING ERRCODE='42501'; END IF; INSERT INTO builder_passports(user_id,username,headline) VALUES(auth.uid(),lower(btrim(_username)),btrim(_headline)) ON CONFLICT(user_id) DO UPDATE SET username=excluded.username,headline=excluded.headline; END $$;
REVOKE ALL ON FUNCTION public.save_builder_passport(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_builder_passport(text,text) TO authenticated;
CREATE TABLE public.builder_endorsements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject_id uuid NOT NULL REFERENCES public.profiles(id),author_id uuid NOT NULL REFERENCES public.profiles(id),request_id uuid NOT NULL REFERENCES public.connect_requests(id),skill text NOT NULL CHECK(length(skill) BETWEEN 2 AND 80),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(subject_id,author_id,skill));
GRANT SELECT,INSERT ON public.builder_endorsements TO authenticated; GRANT SELECT ON public.builder_endorsements TO anon; GRANT ALL ON public.builder_endorsements TO service_role;
ALTER TABLE public.builder_endorsements ENABLE ROW LEVEL SECURITY;
CREATE POLICY endorsement_public ON public.builder_endorsements FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY endorsement_participant ON public.builder_endorsements FOR INSERT TO authenticated WITH CHECK(author_id=auth.uid() AND author_id<>subject_id AND NOT EXISTS(SELECT 1 FROM profiles WHERE id=subject_id AND is_demo) AND EXISTS(SELECT 1 FROM connect_requests r JOIN projects p ON p.id=r.project_id WHERE r.id=request_id AND r.status='accepted' AND auth.uid() IN(r.applicant_id,p.user_id) AND subject_id IN(r.applicant_id,p.user_id)));
CREATE TABLE public.project_merger_proposals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_project uuid NOT NULL REFERENCES public.projects(id),target_project uuid NOT NULL REFERENCES public.projects(id),proposer_id uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','accepted','declined','withdrawn')),terms text NOT NULL CHECK(length(terms) BETWEEN 10 AND 2000),risk_tolerance text NOT NULL CHECK(risk_tolerance IN('low','balanced','high')),created_at timestamptz NOT NULL DEFAULT now(),CHECK(source_project<>target_project));
GRANT SELECT ON public.project_merger_proposals TO authenticated; GRANT ALL ON public.project_merger_proposals TO service_role;
ALTER TABLE public.project_merger_proposals ENABLE ROW LEVEL SECURITY;
CREATE POLICY merger_participants ON public.project_merger_proposals FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM projects p WHERE p.id IN(source_project,target_project) AND p.user_id=auth.uid()));
CREATE FUNCTION public.propose_merger(_source uuid,_target uuid,_terms text,_risk text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mid uuid; BEGIN IF NOT EXISTS(SELECT 1 FROM projects WHERE id=_source AND user_id=auth.uid() AND NOT is_demo) OR NOT EXISTS(SELECT 1 FROM projects WHERE id=_target AND user_id<>auth.uid() AND NOT is_demo) THEN RAISE EXCEPTION 'Two real projects with distinct owners required' USING ERRCODE='42501'; END IF; INSERT INTO project_merger_proposals(source_project,target_project,proposer_id,terms,risk_tolerance) VALUES(_source,_target,auth.uid(),_terms,_risk) RETURNING id INTO mid; RETURN mid; END $$;
REVOKE ALL ON FUNCTION public.propose_merger(uuid,uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.propose_merger(uuid,uuid,text,text) TO authenticated;
CREATE FUNCTION public.respond_merger(_proposal uuid,_decision text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _decision NOT IN('accepted','declined','withdrawn') THEN RAISE EXCEPTION 'Invalid decision'; END IF; UPDATE project_merger_proposals m SET status=_decision WHERE m.id=_proposal AND m.status='pending' AND ((_decision='withdrawn' AND m.proposer_id=auth.uid()) OR (_decision IN('accepted','declined') AND EXISTS(SELECT 1 FROM projects p WHERE p.id=m.target_project AND p.user_id=auth.uid()))); IF NOT FOUND THEN RAISE EXCEPTION 'Pending proposal participant required' USING ERRCODE='42501'; END IF; END $$;
REVOKE ALL ON FUNCTION public.respond_merger(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.respond_merger(uuid,text) TO authenticated;
CREATE TABLE public.scout_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),project_id uuid NOT NULL REFERENCES public.projects(id),requested_by uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','completed','paused')),pause_reason text,lease_token uuid,lease_until timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.scout_runs TO authenticated; GRANT ALL ON public.scout_runs TO service_role;
ALTER TABLE public.scout_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY scout_run_members ON public.scout_runs FOR SELECT TO authenticated USING(public.workspace_access(workspace_id));
CREATE UNIQUE INDEX scout_active_project ON public.scout_runs(project_id) WHERE status IN('queued','running','paused');
CREATE TABLE public.scout_candidates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_id uuid NOT NULL REFERENCES public.scout_runs(id),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),project_id uuid NOT NULL REFERENCES public.projects(id),source text NOT NULL CHECK(source IN('github','huggingface')),handle text NOT NULL,source_url text NOT NULL,evidence_summary text NOT NULL,draft_pitch text NOT NULL,status text NOT NULL DEFAULT 'review' CHECK(status IN('review','dismissed','approved')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,source,handle));
GRANT SELECT ON public.scout_candidates TO authenticated; GRANT ALL ON public.scout_candidates TO service_role;
ALTER TABLE public.scout_candidates ENABLE ROW LEVEL SECURITY;
CREATE POLICY scout_candidate_members ON public.scout_candidates FOR SELECT TO authenticated USING(public.workspace_access(workspace_id));
CREATE TABLE public.scout_processed_items(run_id uuid NOT NULL REFERENCES public.scout_runs(id),item_key text NOT NULL,completed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(run_id,item_key));
GRANT ALL ON public.scout_processed_items TO service_role; ALTER TABLE public.scout_processed_items ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.queue_scout(_workspace uuid,_project uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; BEGIN IF NOT public.workspace_access(_workspace,true) OR NOT EXISTS(SELECT 1 FROM workspace_projects wp JOIN projects p ON p.id=wp.project_id JOIN workspaces w ON w.id=wp.workspace_id WHERE wp.workspace_id=_workspace AND p.id=_project AND NOT p.is_demo AND NOT w.is_demo) THEN RAISE EXCEPTION 'Admin and real portfolio project required' USING ERRCODE='42501'; END IF; INSERT INTO scout_runs(workspace_id,project_id,requested_by) VALUES(_workspace,_project,auth.uid()) RETURNING id INTO rid; RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.queue_scout(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.queue_scout(uuid,uuid) TO authenticated;
CREATE FUNCTION public.claim_scout_run(_run uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE token uuid; BEGIN UPDATE scout_runs SET status='running',lease_token=gen_random_uuid(),lease_until=now()+interval '10 minutes' WHERE id=_run AND status='queued' RETURNING lease_token INTO token; RETURN token; END $$;
REVOKE ALL ON FUNCTION public.claim_scout_run(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_scout_run(uuid) TO service_role;
CREATE FUNCTION public.finish_scout_item(_run uuid,_token uuid,_source text,_handle text,_url text,_summary text,_pitch text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r scout_runs; BEGIN SELECT * INTO r FROM scout_runs WHERE id=_run FOR UPDATE; IF r.status<>'running' OR r.lease_token IS DISTINCT FROM _token OR r.lease_until<now() THEN RAISE EXCEPTION 'Scout lease expired'; END IF; INSERT INTO scout_candidates(run_id,workspace_id,project_id,source,handle,source_url,evidence_summary,draft_pitch) VALUES(r.id,r.workspace_id,r.project_id,_source,_handle,_url,_summary,_pitch) ON CONFLICT(project_id,source,handle) DO NOTHING; INSERT INTO scout_processed_items(run_id,item_key) VALUES(_run,_source||':'||_handle) ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.finish_scout_item(uuid,uuid,text,text,text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finish_scout_item(uuid,uuid,text,text,text,text,text) TO service_role;
CREATE FUNCTION public.review_scout_candidate(_candidate uuid,_status text,_draft text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _status NOT IN('approved','dismissed') OR length(_draft)>1000 THEN RAISE EXCEPTION 'Invalid review'; END IF; UPDATE scout_candidates SET status=_status,draft_pitch=_draft WHERE id=_candidate AND public.workspace_access(workspace_id,true); IF NOT FOUND THEN RAISE EXCEPTION 'Admin required' USING ERRCODE='42501'; END IF; END $$;
REVOKE ALL ON FUNCTION public.review_scout_candidate(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_scout_candidate(uuid,text,text) TO authenticated;
CREATE TABLE public.reciprocal_match_alerts(project_id uuid NOT NULL REFERENCES public.projects(id),builder_id uuid NOT NULL REFERENCES public.profiles(id),similarity double precision NOT NULL CHECK(similarity>0.90 AND similarity<=1),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(project_id,builder_id));
GRANT SELECT ON public.reciprocal_match_alerts TO authenticated; GRANT ALL ON public.reciprocal_match_alerts TO service_role;
ALTER TABLE public.reciprocal_match_alerts ENABLE ROW LEVEL SECURITY;
CREATE POLICY reciprocal_participants ON public.reciprocal_match_alerts FOR SELECT TO authenticated USING(builder_id=auth.uid() OR EXISTS(SELECT 1 FROM projects WHERE id=project_id AND user_id=auth.uid()));
CREATE FUNCTION public.refresh_reciprocal_alerts() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE r record; n integer:=0; BEGIN FOR r IN SELECT p.id AS pid,p.user_id,b.id AS bid,1-(pe.embedding <=> be.embedding) AS sim FROM projects p JOIN project_embeddings pe ON pe.project_id=p.id JOIN profile_embeddings be ON true JOIN profiles b ON b.id=be.profile_id JOIN builder_preferences bp ON bp.user_id=b.id WHERE bp.available AND NOT b.is_demo AND NOT p.is_demo AND p.user_id<>b.id AND 1-(pe.embedding <=> be.embedding)>0.90 AND NOT EXISTS(SELECT 1 FROM reciprocal_match_alerts a WHERE a.project_id=p.id AND a.builder_id=b.id) ORDER BY 1-(pe.embedding <=> be.embedding) DESC LIMIT 20 LOOP INSERT INTO reciprocal_match_alerts VALUES(r.pid,r.bid,r.sim,now()) ON CONFLICT DO NOTHING; IF FOUND THEN INSERT INTO notifications(user_id,type,title,message) VALUES(r.bid,'new_connect_request','Reciprocal match','A project matches your available builder profile above 90%: /p/'||r.pid),(r.user_id,'new_connect_request','Reciprocal match','An available builder matches above 90%. Review your talent pipeline.'); n:=n+1; END IF; END LOOP; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.refresh_reciprocal_alerts() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.refresh_reciprocal_alerts() TO service_role;
